export default function Animation({ progress }) {
  // ---------- helpers ----------
  const clamp01 = (v) => Math.max(0, Math.min(1, v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const smooth = (t) => t * t * (3 - 2 * t);
  const ease = (t) => smooth(clamp01(t));

  // phases spread across timeline
  const pConnect = ease((progress - 0.06) / 0.22); // wire "connects"
  const pFlow = ease((progress - 0.18) / 0.55); // electrons start and continue flowing
  const pPower = ease((progress - 0.40) / 0.55); // device powers up / light brightens
  const pSteady = ease((progress - 0.70) / 0.30); // stable running state

  // subtle breathing for "active" glow (still derived from progress)
  const pulse = 0.5 + 0.5 * Math.sin(progress * Math.PI * 2 * 2.2);

  // layout constants
  const W = 1000,
    H = 560;
  const margin = 24;

  // Battery placement (left)
  const batX = 120,
    batY = 170,
    batW = 240,
    batH = 260;

  // Device placement (right)
  const devX = 640,
    devY = 150,
    devW = 260,
    devH = 300;

  // Circuit endpoints
  const anodeX = batX + 46,
    anodeY = batY + batH * 0.52;
  const cathodeX = batX + batW - 46,
    cathodeY = batY + batH * 0.52;

  const devLeftX = devX + 24,
    devLeftY = devY + devH * 0.52;
  const devRightX = devX + devW - 24,
    devRightY = devY + devH * 0.52;

  // Wires: two clean routes (top and bottom), no crossing
  // Top wire: from cathode -> device right terminal
  const topY = 110;
  const topPath = `M ${cathodeX} ${cathodeY}
                   C ${cathodeX + 90} ${cathodeY - 120}, ${devRightX - 90} ${topY}, ${devRightX} ${devRightY}`;

  // Bottom wire: from device left terminal -> anode
  const bottomY = 470;
  const bottomPath = `M ${devLeftX} ${devLeftY}
                      C ${devLeftX - 120} ${devLeftY + 140}, ${anodeX + 120} ${bottomY}, ${anodeX} ${anodeY}`;

  // "Connection" reveal: draw wires as if they extend out from battery and device
  const wireOpacity = lerp(0.15, 1, pConnect);
  const wireActive = pFlow;

  // Electron motion along external circuit: anode -> device -> cathode (as narration says)
  // We'll animate electrons along bottom wire (anode to device left), through device (left to right),
  // then along top wire (device right to cathode).
  const pathLenBottom = 1; // normalized
  const pathLenInside = 0.35;
  const pathLenTop = 1;

  // Convert a normalized t into a point along a cubic Bezier (for bottom/top wires)
  const cubicPoint = (x0, y0, x1, y1, x2, y2, x3, y3, t) => {
    const u = 1 - t;
    const tt = t * t;
    const uu = u * u;
    const uuu = uu * u;
    const ttt = tt * t;
    const x = uuu * x0 + 3 * uu * t * x1 + 3 * u * tt * x2 + ttt * x3;
    const y = uuu * y0 + 3 * uu * t * y1 + 3 * u * tt * y2 + ttt * y3;
    return { x, y };
  };

  // Bottom path control points (match bottomPath)
  const b0 = { x: devLeftX, y: devLeftY };
  const b1 = { x: devLeftX - 120, y: devLeftY + 140 };
  const b2 = { x: anodeX + 120, y: bottomY };
  const b3 = { x: anodeX, y: anodeY };

  // Top path control points (match topPath but reversed direction for electrons: device right -> cathode)
  const t0 = { x: devRightX, y: devRightY };
  const t1 = { x: devRightX - 90, y: topY };
  const t2 = { x: cathodeX + 90, y: cathodeY - 120 };
  const t3 = { x: cathodeX, y: cathodeY };

  // Inside device path: straight-ish channel from left terminal to right terminal
  const insideY = devY + devH * 0.52;
  const insideX0 = devLeftX + 10;
  const insideX1 = devRightX - 10;

  // Electron stream parameters
  const eCount = 7; // real repeated agents
  const streamSpeed = 1.65; // cycles over progress
  const streamPhase = (progress * streamSpeed) % 1;

  // Device "result": bulb/LED brightness and a small battery energy bar decreasing a bit
  const ledOn = pPower;
  const ledGlow = lerp(0, 1, ledOn) * (0.65 + 0.35 * pulse);
  const screenOn = lerp(0.1, 1, pPower);
  const energyRemaining = lerp(1, 0.62, clamp01((progress - 0.35) / 0.65)); // drains but stays readable

  // Battery internal separation highlight (anode/cathode emphasis)
  const sepShift = lerp(0, 10, pConnect);
  const ionDrift = lerp(0, 1, pFlow);

  // Label sizing helper (simple, conservative)
  const labelPill = (x, y, text, accent = "#38bdf8") => {
    const fs = 18;
    const padX = 12;
    const padY = 8;
    const w = Math.max(70, text.length * fs * 0.55 + padX * 2);
    const h = fs * 1.4 + padY;
    const rx = 12;
    // keep within safe margins (basic clamp)
    const cx = Math.max(margin + w / 2, Math.min(W - margin - w / 2, x));
    const cy = Math.max(margin + h / 2, Math.min(H - margin - h / 2, y));
    return (
      <g>
        <rect
          x={cx - w / 2}
          y={cy - h / 2}
          width={w}
          height={h}
          rx={rx}
          fill="#0b1224"
          stroke="#94a3b8"
          strokeWidth="1.5"
          opacity="0.95"
        />
        <text
          x={cx}
          y={cy + 6}
          textAnchor="middle"
          fontSize={fs}
          fontWeight="700"
          fill="#f1f5f9"
        >
          {text}
        </text>
        <rect
          x={cx - w / 2}
          y={cy - h / 2}
          width={6}
          height={h}
          rx={rx}
          fill={accent}
          opacity="0.95"
        />
      </g>
    );
  };

  // ---------- render ----------
  return (
    <svg viewBox="0 0 1000 560" width="100%" height="100%" role="img" aria-label="Energy flow from battery through external circuit powering a device">
      {/* background */}
      <g aria-label="background">
        <rect x="0" y="0" width="1000" height="560" fill="#020617" />
        <rect x={margin} y={margin} width={W - margin * 2} height={H - margin * 2} rx="18" fill="none" stroke="#334155" strokeWidth="2" opacity="0.55" />
        <line x1={margin} y1={520} x2={W - margin} y2={520} stroke="#1f3b5a" strokeWidth="2" opacity="0.6" />
      </g>

      {/* apparatus/body: battery + device */}
      <g aria-label="apparatus-body">
        {/* Battery outer body */}
        <rect x={batX} y={batY} width={batW} height={batH} rx="26" fill="#64748b" opacity="0.95" stroke="#cbd5e1" strokeWidth="2" />
        {/* Battery cap */}
        <rect x={batX + batW - 44} y={batY + 18} width={30} height={44} rx="8" fill="#94a3b8" opacity="0.95" stroke="#e2e8f0" strokeWidth="2" />
        {/* Cutaway window */}
        <path
          d={`
            M ${batX + 22} ${batY + 26}
            H ${batX + batW - 22}
            V ${batY + batH - 26}
            H ${batX + 22}
            Z
            M ${batX + 40} ${batY + 56}
            H ${batX + batW - 40}
            V ${batY + batH - 56}
            H ${batX + 40}
            Z
          `}
          fill="#64748b"
          fillRule="evenodd"
          opacity="0.98"
        />
        {/* Exposed interior backing */}
        <rect x={batX + 40} y={batY + 56} width={batW - 80} height={batH - 112} rx="18" fill="#94a3b8" opacity="0.95" />

        {/* Device outer body */}
        <rect x={devX} y={devY} width={devW} height={devH} rx="34" fill="#60a5fa" opacity="0.92" stroke="#e2e8f0" strokeWidth="2" />
        {/* Device screen / panel */}
        <rect
          x={devX + 34}
          y={devY + 36}
          width={devW - 68}
          height={110}
          rx="18"
          fill="#22d3ee"
          opacity={lerp(0.25, 0.9, screenOn)}
          stroke="#e2e8f0"
          strokeWidth="2"
        />
        {/* LED/bulb dome */}
        <ellipse cx={devX + devW / 2} cy={devY + 220} rx="62" ry="46" fill="#fbbf24" opacity={lerp(0.25, 0.95, ledOn)} stroke="#fde68a" strokeWidth="2" />
        {/* LED base */}
        <rect x={devX + devW / 2 - 48} y={devY + 250} width={96} height={46} rx="14" fill="#94a3b8" opacity="0.95" stroke="#e2e8f0" strokeWidth="2" />
      </g>

      {/* internal-parts */}
      <g aria-label="internal-parts">
        {/* Battery internal anode/cathode blocks */}
        <rect
          x={batX + 58}
          y={batY + 86}
          width={(batW - 116) / 2 - 10}
          height={batH - 172}
          rx="14"
          fill="#fb7185"
          opacity="0.95"
        />
        <rect
          x={batX + 58 + (batW - 116) / 2 + 10}
          y={batY + 86}
          width={(batW - 116) / 2 - 10}
          height={batH - 172}
          rx="14"
          fill="#4ade80"
          opacity="0.95"
        />
        {/* Separator stripe */}
        <rect
          x={batX + batW / 2 - 10 + sepShift}
          y={batY + 86}
          width={20}
          height={batH - 172}
          rx="10"
          fill="#f1f5f9"
          opacity={lerp(0.25, 0.85, pConnect)}
        />

        {/* Device internal "resistor/coil" channel */}
        <path
          d={`
            M ${devLeftX + 18} ${insideY}
            C ${devLeftX + 70} ${insideY - 40}, ${devLeftX + 120} ${insideY + 40}, ${devLeftX + 170} ${insideY}
            C ${devLeftX + 220} ${insideY - 40}, ${devLeftX + 270} ${insideY + 40}, ${devRightX - 18} ${insideY}
          `}
          fill="none"
          stroke="#0b1224"
          strokeWidth="14"
          strokeLinecap="round"
          opacity="0.35"
        />
        <path
          d={`
            M ${devLeftX + 18} ${insideY}
            C ${devLeftX + 70} ${insideY - 40}, ${devLeftX + 120} ${insideY + 40}, ${devLeftX + 170} ${insideY}
            C ${devLeftX + 220} ${insideY - 40}, ${devLeftX + 270} ${insideY + 40}, ${devRightX - 18} ${insideY}
          `}
          fill="none"
          stroke="#f1f5f9"
          strokeWidth="4"
          strokeLinecap="round"
          opacity={lerp(0.35, 0.95, pConnect)}
        />

        {/* Terminals */}
        <circle cx={anodeX} cy={anodeY} r="10" fill="#fb7185" opacity="0.98" />
        <circle cx={cathodeX} cy={cathodeY} r="10" fill="#4ade80" opacity="0.98" />
        <circle cx={devLeftX} cy={devLeftY} r="10" fill="#94a3b8" opacity="0.98" />
        <circle cx={devRightX} cy={devRightY} r="10" fill="#94a3b8" opacity="0.98" />
      </g>

      {/* energy-or-material-paths */}
      <g aria-label="energy-or-material-paths">
        {/* Wire glow (active) */}
        <path d={topPath} fill="none" stroke="#22d3ee" strokeWidth="10" strokeLinecap="round" opacity={0.12 * wireActive} />
        <path d={bottomPath} fill="none" stroke="#22d3ee" strokeWidth="10" strokeLinecap="round" opacity={0.12 * wireActive} />

        {/* Wires */}
        <path d={topPath} fill="none" stroke="#94a3b8" strokeWidth="5" strokeLinecap="round" opacity={wireOpacity} />
        <path d={bottomPath} fill="none" stroke="#94a3b8" strokeWidth="5" strokeLinecap="round" opacity={wireOpacity} />

        {/* Direction arrows (subtle, appear with flow) */}
        <polygon
          points={`${devRightX - 34},${topY + 18} ${devRightX - 10},${topY + 6} ${devRightX - 30},${topY - 10}`}
          fill="#22d3ee"
          opacity={0.75 * pFlow}
        />
        <polygon
          points={`${anodeX + 34},${bottomY - 18} ${anodeX + 10},${bottomY - 6} ${anodeX + 30},${bottomY + 10}`}
          fill="#22d3ee"
          opacity={0.75 * pFlow}
        />
      </g>

      {/* moving-agents */}
      <g aria-label="moving-agents">
        {/* A few ions shifting inside battery (small drift) */}
        <circle
          cx={lerp(batX + 120, batX + 140, ionDrift)}
          cy={batY + 140}
          r="8"
          fill="#fbbf24"
          opacity={lerp(0.15, 0.85, pFlow)}
        />
        <circle
          cx={lerp(batX + 210, batX + 190, ionDrift)}
          cy={batY + 220}
          r="7"
          fill="#fbbf24"
          opacity={lerp(0.15, 0.75, pFlow)}
        />

        {/* Electron stream: anode -> device -> cathode */}
        {(() => {
          const dots = [];
          for (let i = 0; i < eCount; i++) {
            // each dot offset along the loop
            const u = (streamPhase + i / eCount) % 1;
            // gate appearance: once connected, then stronger with flow
            const a = lerp(0, 1, pConnect) * lerp(0.2, 1, pFlow);
            // segmenting the loop: bottom (0..0.45), inside (0.45..0.65), top (0.65..1)
            let x = 0,
              y = 0;

            if (u < 0.45) {
              // bottom path direction should go anode -> device left, but our bottomPath is device->anode.
              // so we invert t.
              const t = 1 - u / 0.45;
              const pt = cubicPoint(b0.x, b0.y, b1.x, b1.y, b2.x, b2.y, b3.x, b3.y, t);
              x = pt.x;
              y = pt.y;
            } else if (u < 0.65) {
              const t = (u - 0.45) / 0.20;
              x = lerp(anodeX + 16, insideX1, t);
              y = lerp(anodeY, insideY, ease(t));
            } else {
              const t = (u - 0.65) / 0.35;
              const pt = cubicPoint(t0.x, t0.y, t1.x, t1.y, t2.x, t2.y, t3.x, t3.y, t);
              x = pt.x;
              y = pt.y;
            }

            const r = lerp(4.2, 5.6, 0.5 + 0.5 * Math.sin((u + progress) * Math.PI * 2));
            dots.push(
              <g key={i} transform={`translate(${x} ${y})`}>
                <circle r={r + 4} fill="#22d3ee" opacity={0.10 * a} />
                <circle r={r} fill="#e0f2fe" opacity={0.95 * a} />
              </g>
            );
          }
          return dots;
        })()}
      </g>

      {/* result-state */}
      <g aria-label="result-state">
        {/* LED glow overlay */}
        <ellipse
          cx={devX + devW / 2}
          cy={devY + 220}
          rx={92}
          ry={70}
          fill="#fbbf24"
          opacity={0.18 * ledGlow}
        />
        {/* Light beam cone */}
        <path
          d={`
            M ${devX + devW / 2 - 40} ${devY + 190}
            L ${devX + devW / 2 - 160} ${devY + 70}
            L ${devX + devW / 2 + 160} ${devY + 70}
            L ${devX + devW / 2 + 40} ${devY + 190}
            Z
          `}
          fill="#fde68a"
          opacity={0.08 * ledGlow}
        />

        {/* Battery energy gauge */}
        <rect x={batX + 22} y={batY + batH + 26} width={batW - 44} height={18} rx="9" fill="#0b1224" stroke="#94a3b8" strokeWidth="1.5" opacity="0.95" />
        <rect
          x={batX + 24}
          y={batY + batH + 28}
          width={(batW - 48) * energyRemaining}
          height={14}
          rx="7"
          fill={energyRemaining > 0.75 ? "#4ade80" : energyRemaining > 0.5 ? "#22d3ee" : "#fbbf24"}
          opacity="0.95"
        />

        {/* "Running" indicator on device screen */}
        <rect
          x={devX + 58}
          y={devY + 74}
          width={devW - 116}
          height={34}
          rx="12"
          fill="#0b1224"
          opacity={0.75 * pPower}
        />
        <rect
          x={devX + 62}
          y={devY + 78}
          width={(devW - 124) * lerp(0.12, 0.92, pSteady)}
          height={26}
          rx="10"
          fill="#22d3ee"
          opacity={0.9 * pPower}
        />
      </g>

      {/* labels */}
      <g aria-label="labels">
        {labelPill(210, 70, "Battery", "#94a3b8")}
        {labelPill(790, 70, "Device", "#60a5fa")}
        {labelPill(170, 450, "Anode (−)", "#fb7185")}
        {labelPill(320, 450, "Cathode (+)", "#4ade80")}
        {labelPill(500, 520, "Electrons flow through the external circuit", "#22d3ee")}
      </g>
    </svg>
  );
}

export default function Animation({ progress }) {
  // ---------- helpers ----------
  const clamp01 = (v) => Math.max(0, Math.min(1, v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const easeInOut = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
  const easeOut = (t) => 1 - Math.pow(1 - t, 3);

  // ---------- phases (spread across timeline) ----------
  const tIntro = easeInOut(clamp01((progress - 0.02) / 0.22)); // spotlight + base battery appears
  const tSplit = easeInOut(clamp01((progress - 0.18) / 0.32)); // battery splits into two types
  const tPrimary = easeInOut(clamp01((progress - 0.34) / 0.28)); // primary drains (non-rechargeable)
  const tSecondary = easeInOut(clamp01((progress - 0.48) / 0.34)); // secondary charges (rechargeable)
  const tResult = easeInOut(clamp01((progress - 0.70) / 0.28)); // final emphasis

  // ---------- layout ----------
  const W = 1000;
  const H = 560;
  const margin = 24;

  // Spotlight sweep
  const spotX = lerp(280, 720, easeInOut(clamp01((progress - 0.02) / 0.55)));
  const spotY = 190;
  const spotR = lerp(210, 240, tIntro);

  // Base battery (center) morphs into two batteries
  const baseY = 250;
  const baseX = 500;
  const baseScale = lerp(0.92, 1.0, tIntro);
  const baseFade = 1 - tSplit; // fades out as it splits

  // Two batteries positions
  const leftX = lerp(500, 290, tSplit);
  const rightX = lerp(500, 710, tSplit);
  const battY = 260;

  // Battery sizes
  const battW = 220;
  const battH = 120;
  const capW = 26;

  // Primary (left) energy drains
  const primaryFill = lerp(0.92, 0.18, tPrimary); // remaining charge
  const primaryGlow = lerp(0.0, 1.0, tPrimary);

  // Secondary (right) charges
  const secondaryFill = lerp(0.25, 0.92, tSecondary);
  const secondaryGlow = lerp(0.0, 1.0, tSecondary);

  // Charger cable + plug appears for secondary
  const cableAlpha = clamp01((tSecondary - 0.05) / 0.35);
  const plugX = 880;
  const plugY = 290;

  // Moving ions/electrons: left flows out to a "device", right flows in from charger
  const deviceAlpha = clamp01((tPrimary - 0.08) / 0.35);
  const deviceX = 120;
  const deviceY = 270;

  // Particle progress along paths
  const pOut = clamp01((progress - 0.36) / 0.38); // left discharge
  const pIn = clamp01((progress - 0.52) / 0.38); // right charge

  // Final emphasis: highlight secondary as ideal for frequent charging
  const secEmph = tResult;
  const priDim = lerp(1.0, 0.75, tResult);

  // ---------- label sizing / placement (manual, non-overlapping) ----------
  const font = 18;
  const pillPadX = 10;
  const pillPadY = 7;
  const textW = (s) => s.length * font * 0.55;

  const labels = [
    { key: "title", text: "Battery types", x: 60, y: 64, size: 24, color: "#f1f5f9" },
    { key: "primary", text: "Primary (alkaline): non‑rechargeable", x: 90, y: 470, size: 18, color: "#f1f5f9" },
    { key: "secondary", text: "Secondary (Li‑ion): rechargeable", x: 560, y: 470, size: 18, color: "#f1f5f9" },
    { key: "drain", text: "discharge →", x: 160, y: 210, size: 16, color: "#fbbf24" },
    { key: "charge", text: "← charge", x: 750, y: 210, size: 16, color: "#22d3ee" },
  ];

  // ---------- SVG path helpers ----------
  const quadPath = (x1, y1, cx, cy, x2, y2) => `M ${x1} ${y1} Q ${cx} ${cy} ${x2} ${y2}`;

  // Discharge path: left battery to device
  const leftPortX = leftX - battW / 2 - 10;
  const leftPortY = battY;
  const toDeviceX = deviceX + 110;
  const toDeviceY = deviceY;
  const dischargePath = quadPath(leftPortX, leftPortY, 210, 190, toDeviceX, toDeviceY);

  // Charge path: charger plug to right battery
  const rightPortX = rightX + battW / 2 + 10;
  const rightPortY = battY;
  const fromPlugX = plugX - 30;
  const fromPlugY = plugY + 10;
  const chargePath = quadPath(fromPlugX, fromPlugY, 820, 210, rightPortX, rightPortY);

  // Particle position along quadratic Bezier
  const bez2 = (x1, y1, cx, cy, x2, y2, t) => {
    const u = 1 - t;
    const x = u * u * x1 + 2 * u * t * cx + t * t * x2;
    const y = u * u * y1 + 2 * u * t * cy + t * t * y2;
    return { x, y };
  };

  const outPos = bez2(leftPortX, leftPortY, 210, 190, toDeviceX, toDeviceY, easeInOut(pOut));
  const inPos = bez2(fromPlugX, fromPlugY, 820, 210, rightPortX, rightPortY, easeInOut(pIn));

  // ---------- colors ----------
  const bg = "#020617";
  const stroke = "#94a3b8";
  const text = "#f1f5f9";
  const primaryBody = "#fbbf24"; // amber
  const secondaryBody = "#38bdf8"; // sky
  const metal = "#94a3b8";
  const innerDark = "#0b1224"; // only for small label pills/holes; not main bodies
  const track = "#64748b";
  const fillPrimary = "#fb923c"; // orange
  const fillSecondary = "#22d3ee"; // cyan
  const danger = "#fb7185";
  const ok = "#4ade80";

  // ---------- battery drawing as function (no components) ----------
  const Battery = ({
    x,
    y,
    bodyFill,
    labelColor,
    fillLevel,
    glow,
    dim,
    polarity,
    accent,
    showCutaway,
  }) => {
    const w = battW;
    const h = battH;
    const r = 26;
    const bx = x - w / 2;
    const by = y - h / 2;

    // Cutaway window (shows internal "chemistry" block + separator)
    const winX = bx + 34;
    const winY = by + 18;
    const winW = w - 68;
    const winH = h - 36;

    // Fill bar inside window
    const barX = winX + 10;
    const barY = winY + winH - 18;
    const barW = winW - 20;
    const barH = 12;
    const barFillW = Math.max(2, barW * fillLevel);

    // Internal parts: anode/cathode blocks (simple)
    const anodeW = (winW - 26) * 0.48;
    const cathW = (winW - 26) * 0.48;
    const midGap = 26;
    const anodeX = winX + 10;
    const cathX = winX + 10 + anodeW + midGap;
    const blockY = winY + 12;
    const blockH = winH - 44;

    const alpha = dim;

    return (
      <g aria-label="battery" transform={`translate(0,0)`} opacity={alpha}>
        {/* glow */}
        <rect
          x={bx - 10}
          y={by - 10}
          width={w + capW + 20}
          height={h + 20}
          rx={r + 12}
          fill={accent}
          opacity={0.12 * glow}
        />
        {/* body */}
        <rect x={bx} y={by} width={w} height={h} rx={r} fill={bodyFill} opacity={0.92} stroke={stroke} strokeWidth={2} />
        {/* cap */}
        <rect x={bx + w} y={by + 28} width={capW} height={h - 56} rx={10} fill={metal} opacity={0.95} stroke={stroke} strokeWidth={2} />
        {/* polarity nub */}
        <rect
          x={bx + w + capW - 6}
          y={by + 44}
          width={12}
          height={h - 88}
          rx={6}
          fill={metal}
          opacity={0.95}
        />
        {/* cutaway window */}
        {showCutaway && (
          <g aria-label="cutaway">
            <rect x={winX} y={winY} width={winW} height={winH} rx={16} fill={"#94a3b8"} opacity={0.18} stroke={stroke} strokeWidth={1.5} />
            {/* internal blocks */}
            <rect x={anodeX} y={blockY} width={anodeW} height={blockH} rx={14} fill={polarity === "primary" ? "#fb7185" : "#a78bfa"} opacity={0.9} />
            <rect x={cathX} y={blockY} width={cathW} height={blockH} rx={14} fill={polarity === "primary" ? "#4ade80" : "#34d399"} opacity={0.9} />
            {/* separator */}
            <rect x={anodeX + anodeW + 6} y={blockY} width={midGap - 12} height={blockH} rx={10} fill={"#e2e8f0"} opacity={0.9} />
            {/* charge track */}
            <rect x={barX} y={barY} width={barW} height={barH} rx={6} fill={track} opacity={0.9} />
            <rect x={barX} y={barY} width={barFillW} height={barH} rx={6} fill={accent} opacity={0.95} />
          </g>
        )}
        {/* terminals */}
        <circle cx={bx + 18} cy={y} r={7} fill={metal} opacity={0.95} />
        <circle cx={bx + w - 18} cy={y} r={7} fill={metal} opacity={0.95} />
      </g>
    );
  };

  // ---------- render ----------
  return (
    <svg viewBox="0 0 1000 560" width="100%" height="100%" role="img" aria-label="Battery types: primary vs secondary">
      {/* defs */}
      <defs>
        <radialGradient id="spot" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#38bdf8" stopOpacity="0.22" />
          <stop offset="60%" stopColor="#38bdf8" stopOpacity="0.08" />
          <stop offset="100%" stopColor="#38bdf8" stopOpacity="0" />
        </radialGradient>
        <linearGradient id="floor" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#0b1224" stopOpacity="0.0" />
          <stop offset="100%" stopColor="#0b1224" stopOpacity="0.55" />
        </linearGradient>
      </defs>

      {/* background */}
      <g aria-label="background">
        <rect x="0" y="0" width={W} height={H} fill={bg} />
        <rect x={margin} y={margin} width={W - 2 * margin} height={H - 2 * margin} rx="18" fill="none" stroke="#334155" strokeWidth="2" opacity="0.9" />
        {/* spotlight */}
        <circle cx={spotX} cy={spotY} r={spotR} fill="url(#spot)" opacity={0.9 * tIntro} />
        {/* floor */}
        <rect x={margin} y={410} width={W - 2 * margin} height={H - 410 - margin} fill="url(#floor)" />
        <line x1={margin} y1={410} x2={W - margin} y2={410} stroke="#475569" strokeWidth={2} opacity={0.9} />
      </g>

      {/* apparatus/body: base battery that splits */}
      <g aria-label="apparatus/body">
        <g transform={`translate(${baseX},${baseY}) scale(${baseScale}) translate(${-baseX},${-baseY})`} opacity={baseFade}>
          <rect x={baseX - 140} y={baseY - 80} width={280} height={160} rx={34} fill="#60a5fa" opacity={0.9} stroke={stroke} strokeWidth={2} />
          <rect x={baseX + 140} y={baseY - 40} width={34} height={80} rx={12} fill={metal} opacity={0.95} stroke={stroke} strokeWidth={2} />
          {/* simple cutaway silhouette window */}
          <path
            d={`M ${baseX - 95} ${baseY - 50}
                h 190
                a 18 18 0 0 1 18 18
                v 64
                a 18 18 0 0 1 -18 18
                h -190
                a 18 18 0 0 1 -18 -18
                v -64
                a 18 18 0 0 1 18 -18
                z`}
            fill="#94a3b8"
            opacity={0.16}
            stroke={stroke}
            strokeWidth={1.5}
          />
          <rect x={baseX - 80} y={baseY - 34} width={70} height={88} rx={16} fill="#fb7185" opacity={0.9} />
          <rect x={baseX + 10} y={baseY - 34} width={70} height={88} rx={16} fill="#34d399" opacity={0.9} />
          <rect x={baseX - 2} y={baseY - 34} width={14} height={88} rx={8} fill="#e2e8f0" opacity={0.9} />
        </g>
      </g>

      {/* internal-parts: the two batteries with cutaways */}
      <g aria-label="internal-parts">
        {/* left: primary */}
        <g transform={`translate(${leftX},${battY}) translate(${-leftX},${-battY})`}>
          {Battery({
            x: leftX,
            y: battY,
            bodyFill: primaryBody,
            labelColor: text,
            fillLevel: primaryFill,
            glow: primaryGlow,
            dim: priDim,
            polarity: "primary",
            accent: fillPrimary,
            showCutaway: true,
          })}
        </g>

        {/* right: secondary */}
        <g transform={`translate(${rightX},${battY}) translate(${-rightX},${-battY})`}>
          {Battery({
            x: rightX,
            y: battY,
            bodyFill: secondaryBody,
            labelColor: text,
            fillLevel: secondaryFill,
            glow: secondaryGlow + 0.35 * secEmph,
            dim: 1,
            polarity: "secondary",
            accent: fillSecondary,
            showCutaway: true,
          })}
          {/* emphasis ring */}
          <ellipse
            cx={rightX}
            cy={battY}
            rx={150}
            ry={95}
            fill="none"
            stroke={fillSecondary}
            strokeWidth={3}
            opacity={0.25 * secEmph}
          />
        </g>
      </g>

      {/* energy-or-material-paths */}
      <g aria-label="energy-or-material-paths">
        {/* discharge path */}
        <path d={dischargePath} fill="none" stroke="#fbbf24" strokeWidth={3} opacity={0.55 * deviceAlpha} />
        <path d={dischargePath} fill="none" stroke="#fbbf24" strokeWidth={9} opacity={0.10 * deviceAlpha} />
        {/* arrow head near device */}
        <polygon
          points={`${toDeviceX - 10},${toDeviceY - 8} ${toDeviceX + 10},${toDeviceY} ${toDeviceX - 10},${toDeviceY + 8}`}
          fill="#fbbf24"
          opacity={0.7 * deviceAlpha}
        />

        {/* charge path */}
        <path d={chargePath} fill="none" stroke="#22d3ee" strokeWidth={3} opacity={0.65 * cableAlpha} />
        <path d={chargePath} fill="none" stroke="#22d3ee" strokeWidth={9} opacity={0.12 * cableAlpha} />
        {/* arrow head near battery */}
        <polygon
          points={`${rightPortX + 10},${rightPortY - 8} ${rightPortX - 10},${rightPortY} ${rightPortX + 10},${rightPortY + 8}`}
          fill="#22d3ee"
          opacity={0.75 * cableAlpha}
        />
      </g>

      {/* moving-agents */}
      <g aria-label="moving-agents">
        {/* discharge particle */}
        <g opacity={0.95 * deviceAlpha}>
          <circle cx={outPos.x} cy={outPos.y} r={8} fill="#fbbf24" />
          <circle cx={outPos.x} cy={outPos.y} r={16} fill="#fbbf24" opacity={0.18} />
        </g>

        {/* charge particle */}
        <g opacity={0.95 * cableAlpha}>
          <circle cx={inPos.x} cy={inPos.y} r={8} fill="#22d3ee" />
          <circle cx={inPos.x} cy={inPos.y} r={16} fill="#22d3ee" opacity={0.18} />
        </g>

        {/* subtle "X" over primary recharge to indicate non-rechargeable */}
        <g opacity={0.75 * tPrimary}>
          <line x1={leftX - 70} y1={battY - 70} x2={leftX + 70} y2={battY + 70} stroke={danger} strokeWidth={6} strokeLinecap="round" />
          <line x1={leftX + 70} y1={battY - 70} x2={leftX - 70} y2={battY + 70} stroke={danger} strokeWidth={6} strokeLinecap="round" />
        </g>
      </g>

      {/* result-state: device + charger */}
      <g aria-label="result-state">
        {/* device (left) */}
        <g opacity={deviceAlpha}>
          <rect x={deviceX} y={deviceY - 70} width={220} height={140} rx={26} fill="#64748b" opacity={0.95} stroke={stroke} strokeWidth={2} />
          <rect x={deviceX + 22} y={deviceY - 44} width={176} height={88} rx={18} fill="#94a3b8" opacity={0.95} />
          {/* screen bar "power" */}
          <rect x={deviceX + 42} y={deviceY + 18} width={136} height={14} rx={7} fill={track} opacity={0.95} />
          <rect x={deviceX + 42} y={deviceY + 18} width={lerp(120, 30, tPrimary)} height={14} rx={7} fill={lerpColor(fillPrimary, danger, tPrimary)} opacity={0.95} />
        </g>

        {/* charger (right) */}
        <g opacity={cableAlpha}>
          <rect x={plugX - 40} y={plugY - 55} width={90} height={110} rx={18} fill="#a78bfa" opacity={0.95} stroke={stroke} strokeWidth={2} />
          <rect x={plugX - 18} y={plugY - 18} width={46} height={36} rx={10} fill="#94a3b8" opacity={0.95} />
          <line x1={plugX + 50} y1={plugY - 12} x2={plugX + 80} y2={plugY - 12} stroke={metal} strokeWidth={6} strokeLinecap="round" />
          <line x1={plugX + 50} y1={plugY + 12} x2={plugX + 80} y2={plugY + 12} stroke={metal} strokeWidth={6} strokeLinecap="round" />
          {/* charging indicator */}
          <circle cx={plugX - 12} cy={plugY - 30} r={7} fill={ok} opacity={0.9 * (0.4 + 0.6 * easeInOut(clamp01((progress - 0.58) / 0.25)))} />
        </g>
      </g>

      {/* labels */}
      <g aria-label="labels">
        {/* title pill */}
        <Label x={labels[0].x} y={labels[0].y} text={labels[0].text} size={labels[0].size} accent="#60a5fa" />
        {/* type labels */}
        <g opacity={clamp01((progress - 0.22) / 0.25)}>
          <Label x={labels[1].x} y={labels[1].y} text={labels[1].text} size={labels[1].size} accent={primaryBody} />
          <Label x={labels[2].x} y={labels[2].y} text={labels[2].text} size={labels[2].size} accent={secondaryBody} />
        </g>
        {/* flow labels */}
        <g opacity={0.9 * deviceAlpha}>
          <Label x={labels[3].x} y={labels[3].y} text={labels[3].text} size={labels[3].size} accent="#fbbf24" />
        </g>
        <g opacity={0.9 * cableAlpha}>
          <Label x={labels[4].x} y={labels[4].y} text={labels[4].text} size={labels[4].size} accent="#22d3ee" />
        </g>
      </g>
    </svg>
  );

  // ---------- small inline utilities (kept inside component) ----------
  function lerpColor(a, b, t) {
    // a,b in #rrggbb
    const pa = parseInt(a.slice(1), 16);
    const pb = parseInt(b.slice(1), 16);
    const ar = (pa >> 16) & 255,
      ag = (pa >> 8) & 255,
      ab = pa & 255;
    const br = (pb >> 16) & 255,
      bg = (pb >> 8) & 255,
      bb = pb & 255;
    const rr = Math.round(lerp(ar, br, t));
    const rg = Math.round(lerp(ag, bg, t));
    const rb = Math.round(lerp(ab, bb, t));
    return `rgb(${rr},${rg},${rb})`;
  }

  function Label({ x, y, text: str, size, accent }) {
    const w = textW(str) * (size / font);
    const h = size * 1.5;
    const rx = 12;
    const px = pillPadX;
    const py = pillPadY;
    const bx = Math.max(margin, Math.min(W - margin - (w + 2 * px), x));
    const by = Math.max(margin, Math.min(H - margin - (h + 2 * py), y - h));

    return (
      <g aria-label="label">
        <rect x={bx} y={by} width={w + 2 * px} height={h + 2 * py} rx={rx} fill={innerDark} opacity={0.85} stroke="#475569" strokeWidth={1.5} />
        <rect x={bx} y={by} width={6} height={h + 2 * py} rx={rx} fill={accent} opacity={0.95} />
        <text x={bx + px + 10} y={by + py + h * 0.78} fill={text} fontSize={size} fontWeight={700} fontFamily="ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial">
          {str}
        </text>
      </g>
    );
  }
}
